int verify_replay_state_length(struct xfrm_replay_state_esn *replay_esn, struct nlattr *rp) {
    int expected_len = sizeof(struct xfrm_replay_state_esn);
    int attr_len = nla_len(rp);

    if (!replay_esn || !rp)
        return -EINVAL;

    if (attr_len < expected_len)
